import{_ as e,o as r,c as a,a as o}from"./chunks/plugin-vue_export-helper.B1AaF8Z1.js";const c=JSON.parse('{"title":"kb — база знаний на GraphRAG","description":"Кейс kb: гибридный поиск, временной граф знаний и слой верификации. DCS вырос с 0.18 до 0.61 на EnterpriseRAG-Bench, промахи упали с 0.73 до 0.15.","frontmatter":{"site":"pro","title":"kb — база знаний на GraphRAG","description":"Кейс kb: гибридный поиск, временной граф знаний и слой верификации. DCS вырос с 0.18 до 0.61 на EnterpriseRAG-Bench, промахи упали с 0.73 до 0.15.","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/work/kb"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"kb — база знаний на GraphRAG"}],["meta",{"property":"og:description","content":"Кейс kb: гибридный поиск, временной граф знаний и слой верификации. DCS вырос с 0.18 до 0.61 на EnterpriseRAG-Bench, промахи упали с 0.73 до 0.15."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/work/kb"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"kb — база знаний на GraphRAG"}],["meta",{"name":"twitter:description","content":"Кейс kb: гибридный поиск, временной граф знаний и слой верификации. DCS вырос с 0.18 до 0.61 на EnterpriseRAG-Bench, промахи упали с 0.73 до 0.15."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}]]},"headers":[],"relativePath":"work/kb.md","filePath":"work/kb.md"}'),n={name:"work/kb.md"};function i(d,t,l,s,p,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="kb-—-база-знании-на-graphrag" tabindex="-1">kb — база знаний на GraphRAG <a class="header-anchor" href="#kb-—-база-знании-на-graphrag" aria-label="Permalink to &quot;kb — база знаний на GraphRAG&quot;">​</a></h1><p><strong>Задача.</strong> Ответить на вопрос по коду, документации, задачам и переписке команды. Не «найти похожий абзац», а назвать актуальное значение: какая цена, какая версия, какое решение принято последним.</p><p><strong>Ограничения.</strong> Источники разнородны. Часть фактов устарела, часть противоречит друг другу. Модель должна не просто достать фрагмент, а понять, что он перекрыт более новым.</p><h2 id="что-сделал" tabindex="-1">Что сделал <a class="header-anchor" href="#что-сделал" aria-label="Permalink to &quot;Что сделал&quot;">​</a></h2><ul><li><strong>Гибридный поиск</strong>: dense + BM25 + RRF. Один retrieval не вытягивает и точные термины, и перефразировки.</li><li><strong>Граф знаний</strong>: узлы-сущности и связи между ними, поиск с учётом графа, а не только векторов.</li><li><strong>Graph-of-Thoughts</strong>: оркестрация рассуждения по графу вместо одного вызова модели.</li><li><strong>Временная модель</strong>: строгое вытеснение устаревших фактов и детектор противоречий.</li><li><strong>Слой верификации</strong>: проверка цитат и конфликтов между источниками.</li><li><strong>Парсер юридического корпуса</strong> с золотым набором для проверки извлечения.</li><li><strong>15 коннекторов</strong> и MCP-сервер, чтобы система работала из ассистента, а не из отдельной вкладки.</li></ul><h2 id="доказательство" tabindex="-1">Доказательство <a class="header-anchor" href="#доказательство" aria-label="Permalink to &quot;Доказательство&quot;">​</a></h2><p>Замер на срезе EnterpriseRAG-Bench, 60 вопросов. Каждая ступень добавляет одну возможность.</p><table tabindex="0"><thead><tr><th>Ступень</th><th>DCS</th><th>stale_leak</th><th>miss</th></tr></thead><tbody><tr><td>dense-only</td><td>0.18</td><td>0.09</td><td>0.73</td></tr><tr><td>+ hybrid</td><td>0.27</td><td>0.09</td><td>0.64</td></tr><tr><td>+ rerank</td><td>0.27</td><td>0.27</td><td>0.45</td></tr><tr><td>+ Graph-of-Thoughts</td><td>0.58</td><td>0.06</td><td>0.24</td></tr><tr><td>+ temporal</td><td>0.61</td><td>0.15</td><td>0.15</td></tr></tbody></table><p>DCS — доля ответов с актуальным значением вместо устаревшего. Промахи упали с 73% до 15%. Честная оговорка: 11 вопросов в срезе, один вопрос двигает DCS на 0.09. Это паттерн, не рейтинг.</p><p>Код и таблица замеров: <a href="https://github.com/alterfo/kb" target="_blank" rel="noreferrer">github.com/alterfo/kb</a>.</p><h2 id="что-дальше" tabindex="-1">Что дальше <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше&quot;">​</a></h2><ul><li>Воспроизводимость замера одной командой, чтобы цифры проверял не только я.</li><li>Бюджет задержки для интерактивного режима: сейчас качество важнее скорости.</li><li>Расширение золотого корпуса, чтобы DCS перестал быть шумным на малой выборке.</li></ul>',12)])])}const k=e(n,[["render",i]]);export{c as __pageData,k as default};
